22	// secretPattern matches high-entropy strings that may be secrets.
23	// Note: / is excluded to prevent matching entire file paths as single tokens.
24	// Base64 and JWT tokens are still caught via high-entropy segments between slashes.
25	var secretPattern = regexp.MustCompile(`[A-Za-z0-9+_=-]{10,}`)
26	
27	// credentialedURIPattern matches URLs that embed userinfo with a REDACTEDword, such
28	// as REDACTED or REDACTED These often have
29	// moderate entropy and are not reliably covered by vendor-specific scanners.
30	var credentialedURIPattern = regexp.MustCompile(`(?i)\b[a-z][a-z0-9+.-]{1,31}://[^\s/?#@"'` + "`" + `<>:]*:[^\s/?#@"'` + "`" + `<>]+@[^\s"'` + "`" + `<>]+`)
31	
32	// dbPasswordKeyShape matches a DB-prefixed credential key (vendor prefix +
33	// optional `_word`/`-word` segments + `REDACTEDword`/`REDACTEDwd`/`pwd`). Used to
34	// compose both the env-var assignment regex and the JSON-key regex so the
35	// vendor list stays in one place.
36	const dbPasswordKeyShape = `(?:db|database|pg|postgres|postgresql|mysql|mariadb|redis|mongo|mongodb|sqlserver|mssql|jdbc)(?:[_-]+[a-z0-9]+)*[_-]*(?:REDACTEDword|REDACTEDwd|pwd)` //nolint:gosec // regex literal, not a credential
37	
38	var (
39		jdbcPattern          = regexp.MustCompile(`(?i)\bjdbc:[^\s"'<>` + "`" + `]+`)
40		databaseURLPattern   = regexp.MustCompile(`(?i)\b(?:postgres(?:ql)?|mysql|mariadb|mongodb(?:\+srv)?|redis)://[^\s"'<>` + "`" + `]+`)
41		keywordDSNPattern    = regexp.MustCompile(`(?i)\b[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)(?:\s+[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)){2,}`)
42		semicolonConnPattern = regexp.MustCompile(`(?i)\b[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|"[^"]*"|'[^']*'|[^=;"'\s]+)(?:;[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|"[^"]*"|'[^']*'|[^=;"'\s]+)){2,}`)
43		// credentialValuePattern requires the prefix to start at a non-alphanumeric
44		// boundary, so APP_DB_PASSWORD matches via the leading `_` but mydbREDACTEDword
45		// does not.
46		credentialValuePattern = regexp.MustCompile(`(?i)(?:^|[^A-Za-z0-9])(` + dbPasswordKeyShape + `)\s*=\s*("[^"]*"|'[^']*'|[^\s,;&]+)`)
47	
48		keywordHostPattern      = regexp.MustCompile(`(?i)(?:^|\s)host=`)
49		keywordUserPattern      = regexp.MustCompile(`(?i)(?:^|\s)user=`)
50		semicolonServerPattern  = regexp.MustCompile(`(?i)(?:^|;)\s*(?:server|data source|datasource|addr|address|network address)\s*=`)
51		semicolonUserPattern    = regexp.MustCompile(`(?i)(?:^|;)\s*(?:user id|userid|user|uid)\s*=`)
52		REDACTEDwordAssignmentRegex = regexp.MustCompile(`(?i)(?:^|[?&;\s])(?:REDACTEDword|pwd)=("[^"]*"|'[^']*'|[^&;\s"']+)`)
53		// credentialJSONKeyRegex operates on output of normalizeCredentialJSONKey
54		// (already lowercased, `-`/` `/`.` → `_`), so the `(?i)` flag is unnecessary.
55		credentialJSONKeyRegex  = regexp.MustCompile(`^` + dbPasswordKeyShape + `$`)
56		genericPasswordKeyRegex = regexp.MustCompile(`(?i)^(?:REDACTEDword|REDACTEDwd|pwd)$`)
57	)
58	
59	// entropyThreshold is the minimum Shannon entropy for a string to be considered
60	// a secret. 4.5 was chosen through trial and error: high enough to avoid false
61	// positives on common words and identifiers, low enough to catch typical API keys
62	// and tokens which tend to have entropy well above 5.0.
63	const entropyThreshold = 4.5
64	
65	// RedactedPlaceholder is the replacement text used for redacted secrets.
66	const RedactedPlaceholder = "REDACTED"
67	
68	// placeholderSecretValues lists lowercase values that should be treated as
69	// non-secrets when they appear as a credential value: prior redactions
70	// (REDACTED / [REDACTED] / <REDACTED>), common documentation placeholders,
71	// and obviously-non-real defaults. Values matched by shape (mask runs,
72	// `<…>` brackets, `${…}` shell expansion) are handled separately.
73	var placeholderSecretValues = func() map[string]struct{} {
74		lower := strings.ToLower(RedactedPlaceholder)
75		values := []string{
76			lower, "[" + lower + "]", "<" + lower + ">",
77			"changeme", "example", "placeholder",
78			"your_REDACTEDword", "your_db_REDACTEDword", "your_secret",
79			"secret_here",
80		}
81		out := make(map[string]struct{}, len(values))
82		for _, v := range values {
83			out[v] = struct{}{}
84		}
85		return out
86	}()
87	
88	// RedactedBytes represents transcript data that has been through secret
89	// redaction. Consumers that require pre-redacted input (e.g., compact.Compact,
90	// checkpoint stores) accept this type to enforce the contract at compile time.
91	//
92	// Produced by JSONLBytes (primary constructor) or trusted wrappers for data
93	// previously persisted by checkpoint writers.
94	type RedactedBytes struct {
95		data []byte
96	}
97	
98	// Bytes returns the underlying byte slice.
99	func (r RedactedBytes) Bytes() []byte {
100		return r.data
101	}
102	
103	// Len returns the number of bytes in the redacted payload.
104	func (r RedactedBytes) Len() int {
105		return len(r.data)
106	}
107	
108	// AlreadyRedacted wraps transcript bytes known to already be redacted by a
109	// prior write path. Use this ONLY for trusted sources such as persisted
110	// checkpoint transcripts or controlled test fixtures. For fresh transcript
111	// input, use JSONLBytes.
112	func AlreadyRedacted(data []byte) RedactedBytes {
113		return RedactedBytes{data: data}
114	}
115	
116	var (
117		betterleaksDetector     *detect.Detector
118		betterleaksDetectorOnce sync.Once
119	)
120	
121	func getDetector() *detect.Detector {
122		betterleaksDetectorOnce.Do(func() {
123			d, err := detect.NewDetectorDefaultConfig()
124			if err != nil {
125				return
126			}
127			betterleaksDetector = d
128		})
129		return betterleaksDetector
130	}
131	
132	// region represents a byte range to redact.
133	type region struct{ start, end int }
134	
135	// taggedRegion extends region with a label for typed replacement tokens.
136	// Empty label = secret (produces "REDACTED"). Non-empty = PII (produces "[REDACTED_<LABEL>]").
137	type taggedRegion struct {
138		region
139	
140		label string
141	}
142	
143	type jsonReplacement struct {
144		key      string
145		original string
146		redacted string
147	}
148	
149	type connectionStringRule struct {
150		pattern   *regexp.Regexp
151		hasSecret func(string) bool
152	}
153	
154	var connectionStringRules = []connectionStringRule{
155		{pattern: jdbcPattern, hasSecret: hasJDBCPassword},
156		{pattern: databaseURLPattern, hasSecret: hasDatabaseURLSecret},
157		{pattern: keywordDSNPattern, hasSecret: hasKeywordDSNPassword},
158		{pattern: semicolonConnPattern, hasSecret: hasSemicolonConnectionPassword},
159	}
160	
161	// String replaces secrets and PII in s using layered detection:
162	//  1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
163	//  2. Pattern-based: scanner engines selected via ConfigureScanners —
164	//     betterleaks regex rules (several hundred known secret formats) and/or the
165	//     goredact engine; betterleaks-only when unconfigured
166	//  3. Provider token prefixes: deterministic prefix rules for credential
167	//     formats betterleaks misses in isolation (e.g. Supabase sb_secret_)
168	//  4. Credentialed URIs: URLs containing userinfo REDACTEDwords
169	//  5. Database connection strings: JDBC, keyword DSNs, and semicolon strings
170	//  6. User-defined custom rules: configured via ConfigureCustomRules
171	//  7. Bounded credential key/value pairs: DB_PASSWORD=...
172	//  8. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
173	//
174	// A string is redacted if ANY method flags it.
175	func String(s string) string {
176		return applyRegions(s, detectAllLayers(s))
177	}
178	
179	// detectAllLayers runs the always-on, opt-in, and scanner-configurable
180	// detection layers and returns their tagged regions. The OpenAI Privacy Filter
181	// (the final, network-backed layer) is NOT included — callers that want it
182	// append detectOPF spans to the result before REDACTEDing to applyRegions. See
183	// StringWithPrivacyFilter for the augmented flow.
184	func detectAllLayers(s string) []taggedRegion {
185		var regions []taggedRegion
186	
187		// 1. Entropy-based detection (secrets — always on).
188		for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
189			start, end := loc[0], loc[1]
190	
191			// Don't consume characters that are part of JSON/string escape sequences.
192			// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
193			// (consuming the 'n' from '\n'), and after replacement the '\' would be
194			// followed by 'R' from "REDACTED", creating invalid escape '\R'.
195			// Only skip for known JSON escape letters to avoid trimming real secrets
196			// that happen to follow a literal backslash in decoded content.
197			if start > 0 && s[start-1] == '\\' {
198				switch s[start] {
199				case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
200					start++
201					if end-start < 10 {
202						continue
203					}
204				}
205			}
206	
207			if shannonEntropy(s[start:end]) > entropyThreshold {
208				regions = append(regions, taggedRegion{region: region{start, end}})
209			}
210		}
211	
212		// 2. Pattern-based detection via scanner engines (secrets — selected
213		// via ConfigureScanners; betterleaks-only when unconfigured).
214		if getScanners().betterleaks {
215			if d := getDetector(); d != nil {
216				for _, f := range d.DetectString(s) {
217					// Placeholder-valued findings (changeme, secret_here, mask runs)
218					// stay visible — but only on an exact match: splitting a greedy
219					// finding at a placeholder head can leak a real secret in the tail.
220					if isPlaceholderSecretValue(f.Secret) {
221						continue
222					}
223					searchFrom := 0
224					for {
225						idx := strings.Index(s[searchFrom:], f.Secret)
226						if idx < 0 {
227							break
228						}
229						absIdx := searchFrom + idx
230						regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
231						searchFrom = absIdx + len(f.Secret)
232					}
233				}
234			}
235		}
236		// goredact engine findings (only runs when enabled via ConfigureScanners).
237		regions = append(regions, detectGoredact(s)...)
238	
239		// 3. Provider-specific deterministic token prefixes (secrets — always on).
240		// Catches low-entropy credential formats (e.g. Supabase sb_secret_) that
241		// the entropy and betterleaks layers miss when captured in isolation.
242		regions = append(regions, detectProviderTokens(s)...)
243	
244		// 4. Credentialed URIs (secrets — always on).
245		for _, loc := range credentialedURIPattern.FindAllStringIndex(s, -1) {
246			regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
247		}
248	
249		// 5. Database and connection-string detection (secrets — always on).
250		regions = append(regions, detectConnectionStrings(s)...)
251	
252		// 6. User-defined custom rules (secrets — only runs when configured).
253		regions = append(regions, detectCustomRules(getCustomRulesConfig(), s)...)
254	
255		// 7. Bounded credential key/value detection (secrets — always on).
256		regions = append(regions, detectCredentialValues(s)...)
257	
258		// 8. PII detection (opt-in — only runs when configured).
259		regions = append(regions, detectPII(getPIIConfig(), s)...)
260	
261		return regions
262	}
263	
264	// applyRegions sorts, merges, and replaces the given regions in s, returning
265	// the redacted string. Returns s unchanged when regions is empty.
266	func applyRegions(s string, regions []taggedRegion) string {
267		if len(regions) == 0 {
268			return s
269		}
270	
271		sort.Slice(regions, func(i, j int) bool {
272			if regions[i].start != regions[j].start {
273				return regions[i].start < regions[j].start
274			}
275			if regions[i].end != regions[j].end {
276				return regions[i].end > regions[j].end // larger region first
277			}
278			return regions[i].label < regions[j].label // deterministic tie-break
279		})
280		merged := []taggedRegion{regions[0]}
281		for _, r := range regions[1:] {
282			last := &merged[len(merged)-1]
283			if r.start <= last.end {
284				if r.end > last.end {
285					last.end = r.end
286				}
287				// Keep the existing label (first/larger region wins)
288			} else {
289				merged = append(merged, r)
290			}
291		}
292	
293		var b strings.Builder
294		prev := 0
295		for _, r := range merged {
296			b.WriteString(s[prev:r.start])
297			b.WriteString(replacementToken(r.label))
298			prev = r.end
299		}
300		b.WriteString(s[prev:])
301		return b.String()
302	}
303	
304	func detectConnectionStrings(s string) []taggedRegion {
305		if !strings.ContainsRune(s, '=') {
306			return nil
307		}
308		var regions []taggedRegion
309		for _, rule := range connectionStringRules {
310			regions = append(regions, detectConnectionStringRule(s, rule)...)
311		}
312		return regions
313	}
314	
315	func detectConnectionStringRule(s string, rule connectionStringRule) []taggedRegion {
316		var regions []taggedRegion
317		for _, loc := range rule.pattern.FindAllStringIndex(s, -1) {
318			start, end := loc[0], trimConnectionStringEnd(s, loc[0], loc[1])
319			if start >= end {
320				continue
321			}
322			if rule.hasSecret(s[start:end]) {
323				regions = append(regions, taggedRegion{region: region{start, end}})
324			}
325		}
326		return regions
327	}
328	
329	func trimConnectionStringEnd(s string, start, end int) int {
330		for end > start {
331			switch s[end-1] {
332			case '.', ',', ';', ':', '!', '?', ')', ']':
333				end--
334			default:
335				return end
336			}
337		}
338		return end
339	}
340	
341	func hasJDBCPassword(candidate string) bool {
342		if !strings.HasPrefix(strings.ToLower(candidate), "jdbc:") {
343			return false
344		}
345		return hasNonPlaceholderPasswordAssignment(candidate)
346	}
347	
348	func hasDatabaseURLSecret(candidate string) bool {
349		u, err := url.Parse(candidate)
350		if err != nil || u.Scheme == "" || u.Host == "" {
351			return false
352		}
353		for key, values := range u.Query() {
354			if !isPasswordQueryKey(key) {
355				continue
356			}
357			for _, value := range values {
358				if hasNonPlaceholderPasswordValue(value) {
359					return true
360				}
361			}
362		}
363		return false
364	}
365	
366	func isPasswordQueryKey(key string) bool {
367		return strings.EqualFold(key, "REDACTEDword") || strings.EqualFold(key, "pwd")
368	}
369	
370	func hasKeywordDSNPassword(candidate string) bool {
371		return keywordHostPattern.MatchString(candidate) &&
372			keywordUserPattern.MatchString(candidate) &&
373			hasNonPlaceholderPasswordAssignment(candidate)
374	}
375	
376	func hasSemicolonConnectionPassword(candidate string) bool {
377		return semicolonServerPattern.MatchString(candidate) &&
378			semicolonUserPattern.MatchString(candidate) &&
379			hasNonPlaceholderPasswordAssignment(candidate)
380	}
381	
382	func detectCredentialValues(s string) []taggedRegion {
383		var regions []taggedRegion
384		for _, loc := range credentialValuePattern.FindAllStringSubmatchIndex(s, -1) {
385			if len(loc) < 6 || loc[4] < 0 || loc[5] < 0 {
386				continue
387			}
388			start, end := unquoteRange(s, loc[4], loc[5])
389			if hasNonPlaceholderPasswordValue(s[start:end]) {
390				regions = append(regions, taggedRegion{region: region{start, end}})
391			}
392		}
393		return regions
394	}
395	
396	func unquoteRange(s string, start, end int) (int, int) {
397		if end-start < 2 {
398			return start, end
399		}
400		first, last := s[start], s[end-1]
401		if (first == '"' && last == '"') || (first == '\'' && last == '\'') {
402			return start + 1, end - 1
403		}
404		return start, end
405	}
406	
407	func hasNonPlaceholderPasswordAssignment(candidate string) bool {
408		for _, loc := range REDACTEDwordAssignmentRegex.FindAllStringSubmatchIndex(candidate, -1) {
409			if len(loc) >= 4 && loc[2] >= 0 && loc[3] >= 0 {
410				start, end := unquoteRange(candidate, loc[2], loc[3])
411				if hasNonPlaceholderPasswordValue(candidate[start:end]) {
412					return true
413				}
414			}
415		}
416		return false
417	}
418	
419	func hasNonPlaceholderPasswordValue(value string) bool {
420		return value != "" && !isPlaceholderSecretValue(value)
421	}
422	
423	func isPlaceholderSecretValue(value string) bool {
424		trimmed := strings.Trim(strings.TrimSpace(value), `"'`)
425		if trimmed == "" {
426			return true
427		}
428		if isBracketedPlaceholder(trimmed) {
429			return true
430		}
431		normalized := strings.ToLower(trimmed)
432		if strings.HasPrefix(normalized, "${") && strings.HasSuffix(normalized, "}") {
433			return true
434		}
435		if _, ok := placeholderSecretValues[normalized]; ok {
436			return true
437		}
438		return isRepeatedCharPlaceholder(normalized)
439	}
440	
441	// bracketedPlaceholderInteriorRE matches the inside of a "<…>" placeholder
442	// shape: lowercase letters joined by `-` or `_`. Digits, mixed case, and
443	// special chars are rejected so values like `<hunter2>` or `<RealPassword>`
444	// still fall through to redaction.
445	var bracketedPlaceholderInteriorRE = regexp.MustCompile(`^[a-z][a-z_-]*$`)
446	
447	// isBracketedPlaceholder reports whether s is a "<name>" doc placeholder
448	// (e.g. "<REDACTEDword>", "<your-db-REDACTEDword>"). The minimum total length of 5
449	// keeps this from firing on `<a>` / `<ab>`.
450	func isBracketedPlaceholder(s string) bool {
451		if len(s) < 5 || s[0] != '<' || s[len(s)-1] != '>' {
452			return false
453		}
454		return bracketedPlaceholderInteriorRE.MatchString(s[1 : len(s)-1])
455	}
456	
457	// isRepeatedCharPlaceholder reports whether s is a run of a single masking
458	// character commonly used to redact values in docs and screenshots, e.g.
459	// "***", "xxxx", "....", "----". The minimum length of 3 keeps single-char
460	// or 2-char values like `x` or `**` from being treated as masks.
461	func isRepeatedCharPlaceholder(s string) bool {
462		if len(s) < 3 {
463			return false
464		}
465		first := s[0]
466		switch first {
467		case '*', 'x', '.', '-':
468		default:
469			return false
470		}
471		for i := 1; i < len(s); i++ {
472			if s[i] != first {
473				return false
474			}
475		}
476		return true
477	}
478	
479	func isCredentialJSONSecretKey(key string, credentialContext bool) bool {
480		normalized := normalizeCredentialJSONKey(key)
481		if credentialJSONKeyRegex.MatchString(normalized) {
482			return true
483		}
484		return credentialContext && genericPasswordKeyRegex.MatchString(normalized)
485	}
486	
487	func isCredentialJSONObject(obj map[string]any) bool {
488		var hasHost, hasUser bool
489		for key := range obj {
490			switch normalizeCredentialJSONKey(key) {
491			case "host", "hostname", "server", "addr", "address", "datasource", "data_source":
492				hasHost = true
493			case "user", "username", "userid", "user_id", "uid":
494				hasUser = true
495			}
496			if hasHost && hasUser {
497				return true
498			}
499		}
500		return false
501	}
502	
503	func normalizeCredentialJSONKey(key string) string {
504		key = strings.ToLower(strings.TrimSpace(key))
505		key = strings.ReplaceAll(key, "-", "_")
506		key = strings.ReplaceAll(key, " ", "_")
507		// Flattened-config exporters (Spring, dotnet, Hashicorp Vault) emit dotted keys
508		// like "db.REDACTEDword" or "mysql.root.REDACTEDword"; treat them like underscored.
509		key = strings.ReplaceAll(key, ".", "_")
510		return key
511	}
512	
513	// Bytes is a convenience wrapper around String for []byte content.
514	func Bytes(b []byte) []byte {
515		s := string(b)
516		redacted := String(s)
517		if redacted == s {
518			return b
519		}
520		return []byte(redacted)
521	}
522	
523	// JSONLBytes redacts secrets in JSONL-formatted byte content and returns
524	// the result as RedactedBytes, certifying the output has been through redaction.
525	// Returns ErrScannerDegraded when the goredact scanner degraded while
526	// betterleaks is disabled.
527	func JSONLBytes(b []byte) (RedactedBytes, error) {
528		s := string(b)
529		redacted, err := JSONLContent(s)
530		if err != nil {
531			// Degradation outranks a walk error: callers' errors.Is guards must
532			// see the sentinel so no error path can reach a Bytes fallback.
533			if scannerDegradedSole() {
534				return RedactedBytes{}, fmt.Errorf("%w (content walk also failed: %w)", ErrScannerDegraded, err)
535			}
536			return RedactedBytes{}, err
537		}
538		if scannerDegradedSole() {
539			return RedactedBytes{}, ErrScannerDegraded
540		}
541		if redacted == s {
542			return RedactedBytes{data: b}, nil
543		}
544		return RedactedBytes{data: []byte(redacted)}, nil
545	}
546	
547	// JSONLBytesWithPrivacyFilter augments JSONLBytes with the OpenAI Privacy
548	// Filter. Use only at condensation/export boundaries; per-turn writes must
549	// use JSONLBytes.
550	// Returns ErrScannerDegraded when the goredact scanner degraded while
551	// betterleaks is disabled.
552	func JSONLBytesWithPrivacyFilter(ctx context.Context, b []byte) (RedactedBytes, error) {
553		s := string(b)
554		redacted, err := JSONLContentWithPrivacyFilter(ctx, s)
555		if err != nil {
556			// Degradation outranks a walk error; see JSONLBytes.
557			if scannerDegradedSole() {
558				return RedactedBytes{}, fmt.Errorf("%w (content walk also failed: %w)", ErrScannerDegraded, err)
559			}
560			return RedactedBytes{}, err
561		}
562		if scannerDegradedSole() {
563			return RedactedBytes{}, ErrScannerDegraded
564		}
565		if redacted == s {
566			return RedactedBytes{data: b}, nil
567		}
568		return RedactedBytes{data: []byte(redacted)}, nil
569	}
570	
571	// BytesWithPrivacyFilter augments Bytes with the OpenAI Privacy Filter for
572	// raw (non-JSONL) byte content. Used by checkpoint write paths that handle
573	// metadata files which may or may not be JSONL.
574	func BytesWithPrivacyFilter(ctx context.Context, b []byte) []byte {
575		s := string(b)
576		redacted := StringWithPrivacyFilter(ctx, s)
577		if redacted == s {
578			return b
579		}
580		return []byte(redacted)
581	}
582	
583	// JSONLContent parses each line as JSON to determine which string values
584	// need redaction, then performs targeted replacements on the raw JSON bytes.
585	// Lines with no secrets are returned unchanged, preserving original formatting.
586	//
587	// For multi-line JSON content (e.g., pretty-printed single JSON objects like
588	// OpenCode export), the function first attempts to parse the entire content as
589	// a single JSON value. This ensures field-aware redaction (which skips ID fields)
590	// is used instead of falling back to entropy-based detection on raw text lines,
591	// which would corrupt high-entropy identifiers.
592	//
593	// Large content is sharded across goroutines; output is byte-identical either
594	// way. See jsonlContent.
595	func JSONLContent(content string) (string, error) {
596		return jsonlContentImpl(content, String, concurrencySafeRedactor)
597	}
598	
599	// Whether a per-leaf redactor may be called from several goroutines at once.
600	//
601	// This is a property of the redactor, not of the entry point that supplies it,
602	// so it is REDACTEDed explicitly rather than implied by which internal function a
603	// caller happens to reach: String is pure and shardable, while the OPF flow's
604	// collector closures accumulate into a shared map and slice and are not.
605	const (
606		concurrencySafeRedactor   = true
607		concurrencyUnsafeRedactor = false
608	)
609	
610	// jsonlContentImpl is the body of JSONLContent parameterized by a per-leaf
611	// redactor. JSONLContent REDACTEDes String (regex layers only). The OPF-enabled
612	// flow uses two REDACTEDes: one with a collector that records leaves and returns
613	// identity, one with a redactor that combines regex layers with cached OPF
614	// spans for the recorded leaves.
615	//
616	// concurrencySafe reports whether redactor tolerates concurrent calls; when it
617	// does, large content is sharded across goroutines.
618	func jsonlContentImpl(content string, redactor func(string) string, concurrencySafe bool) (string, error) {
619		if result, handled, err := redactSingleJSONValue(content, redactor); handled {
620			return result, err
621		}
622		lines := strings.Split(content, "\n")
623		if !concurrencySafe {
624			return redactJSONLLines(lines, redactor)
625		}
626		return redactJSONLLinesSharded(lines, redactor)
627	}
628	
629	// redactSingleJSONValue handles the case where the whole content is one JSON
630	// value (e.g. pretty-printed single objects like OpenCode export) so
631	// field-aware redaction is used instead of falling back to entropy-based
632	// detection on raw text lines, which would corrupt high-entropy identifiers.
633	//
634	// handled is false when the content is JSONL, so the caller processes it line by
635	// line. Neither the shard split nor the incremental prefix cache in
636	// checkpoint/redact_cache.go applies to the single-value shape.
637	func redactSingleJSONValue(content string, redactor func(string) string) (result string, handled bool, err error) {
638		trimmed := strings.TrimSpace(content)
639		if len(trimmed) == 0 {
640			return "", false, nil
641		}
642		parsed, ok := parseSingleJSONValue(trimmed)
643		if !ok {
644			return "", false, nil
645		}
646		result, err = applyJSONReplacements(content, collectJSONLReplacements(parsed, redactor))
647		if err != nil {
648			return "", true, err
649		}
650		return result, true, nil
651	}
652	
653	// IsLineDelimited reports whether JSONLContent will redact content line by line
654	// rather than as a single JSON value.
655	//
656	// Callers that split content and redact the pieces separately MUST check this
657	// first. The line path composes -- redact(A+B) == redact(A)+redact(B) for
658	// newline-terminated A -- because each line is redacted in isolation. The
659	// single-JSON-value path does NOT: it is field-aware across the whole document,
660	// so redacting a fragment of it instead falls back to raw regex and entropy
661	// detection over partial JSON, which is the identifier corruption
662	// redactSingleJSONValue exists to avoid.
663	//
664	// A filename is not a safe proxy for this. OpenCode writes a single JSON object
665	// to the same full.jsonl path that other agents write JSONL to.
666	func IsLineDelimited(content []byte) bool {
667		trimmed := bytes.TrimSpace(content)
668		if len(trimmed) == 0 {
669			return false
670		}
671		// Decode stops at the first complete value, so this does not scan a large
672		// JSONL body. Content that is not JSON at all still goes down the line path,
673		// where each line is redacted independently.
674		dec := json.NewDecoder(bytes.NewReader(trimmed))
675		var parsed any
676		if err := dec.Decode(&parsed); err != nil {
677			return true
678		}
679		return !isSingleJSONValue(dec)
680	}
681	
682	// parseSingleJSONValue reports whether s decodes as exactly one JSON value.
683	//
684	// Uses a streaming decoder so a large JSONL input is not copied: Decode stops at
685	// the first complete value, then isSingleJSONValue checks for a second one. A
686	// decode failure is a routing signal, not an error — it just means the content
687	// is not a single JSON value.
688	func parseSingleJSONValue(s string) (any, bool) {
689		dec := json.NewDecoder(strings.NewReader(s))
690		var parsed any
691		if err := dec.Decode(&parsed); err != nil {
692			return nil, false
693		}
694		return parsed, isSingleJSONValue(dec)
695	}
696	
697	// jsonlShardTargetBytes is the rough content size per shard, and hence also the
698	// sharding threshold: content under 2x this yields fewer than two shards and
699	// runs sequentially.
700	//
701	// The win is not purely parallelism: redaction cost per byte climbs with input
702	// size (allocation and GC pressure over one large buffer), so cutting the
703	// content into small pieces is cheaper per byte *and* lets pieces run
704	// concurrently. Measured on a 20MB Codex transcript: 43s sequential vs 2.1s
705	// across 12 shards. Hence a byte-sized shard target rather than one shard per
706	// core, with worker count bounding actual concurrency.
707	const jsonlShardTargetBytes = 1 << 20 // 1MiB
708	
709	// redactJSONLLinesSharded splits lines into contiguous byte-balanced groups,
710	// redacts them concurrently, and rejoins them in order. Output is byte-identical
711	// to redactJSONLLines over the same lines, because each line is redacted in
712	// isolation and shard boundaries fall between lines.
713	//
714	// redactor MUST be safe for concurrent use.
715	func redactJSONLLinesSharded(lines []string, redactor func(string) string) (string, error) {
716		// Balance shards by bytes, not by line count: agent transcripts mix
717		// thousands of short lines with occasional multi-MB tool results, so equal
718		// line counts would leave one oversized shard as the tail.
719		bounds := shardLineBounds(lines, jsonlShardTargetBytes)
720		if len(bounds) < 2 {
721			return redactJSONLLines(lines, redactor)
722		}
723	
724		results := make([]string, len(bounds))
725		g := new(errgroup.Group)
726		g.SetLimit(runtime.GOMAXPROCS(0))
727		for i, b := range bounds {
728			g.Go(func() error {
729				out, err := redactJSONLLines(lines[b.lo:b.hi], redactor)
730				if err != nil {
731					return err
732				}
733				results[i] = out
734				return nil
735			})
736		}
737		if err := g.Wait(); err != nil {
738			return "", fmt.Errorf("redacting JSONL shard: %w", err)
739		}
740	
741		// Shards are contiguous line ranges, so rejoining them with "\n" in order
742		// reproduces the sequential join exactly.
743		return strings.Join(results, "\n"), nil
744	}
745	
746	// lineRange is a half-open range of line indexes forming one shard.
747	type lineRange struct{ lo, hi int }
748	
749	// shardLineBounds groups lines into contiguous ranges of roughly targetBytes
750	// each. A single line larger than targetBytes becomes its own shard rather than
751	// being split, since lines are the indivisible unit of redaction.
752	func shardLineBounds(lines []string, targetBytes int) []lineRange {
753		var bounds []lineRange
754		lo, running := 0, 0
755		for i, line := range lines {
756			running += len(line) + 1 // +1 for the rejoined newline
757			if running >= targetBytes && i+1 < len(lines) {
758				bounds = append(bounds, lineRange{lo: lo, hi: i + 1})
759				lo, running = i+1, 0
760			}
761		}
762		if lo < len(lines) {
763			bounds = append(bounds, lineRange{lo: lo, hi: len(lines)})
764		}
765		return bounds
766	}
767	
768	// redactJSONLLines redacts each line independently and rejoins them with "\n".
769	//
770	// Every line is handled in isolation: no state carries between lines, which is
771	// what makes sharding across goroutines (jsonlContentConcurrent) produce
772	// byte-identical output to a sequential REDACTED. Keep it that way — a redactor or
773	// line rule that depended on earlier lines would silently break that guarantee.
774	func redactJSONLLines(lines []string, redactor func(string) string) (string, error) {
775		var b strings.Builder
776		// Redaction only ever shrinks or preserves length, so the input size is a
777		// sound capacity estimate and avoids repeated doubling of a large buffer.
778		size := len(lines) - 1
779		for _, line := range lines {
780			size += len(line)
781		}
782		if size > 0 {
783			b.Grow(size)
784		}
785		for i, line := range lines {
786			if i > 0 {
787				b.WriteByte('\n')
788			}
789			lineTrimmed := strings.TrimSpace(line)
790			if lineTrimmed == "" {
791				b.WriteString(line)
792				continue
793			}
794			var parsed any
795			if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
796				b.WriteString(redactor(line))
797				continue
798			}
799			result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed, redactor))
800			if err != nil {
801				return "", err
802			}
803			b.WriteString(result)
804		}
805		return b.String(), nil
806	}
807	
808	// StringWithPrivacyFilter augments String with the OpenAI Privacy Filter.
809	// Use only at condensation/export boundaries; per-turn writes must use
810	// String to avoid the OPF shell-out cost inside the agent loop.
811	func StringWithPrivacyFilter(ctx context.Context, s string) string {
812		regions := detectAllLayers(s)
813		regions = append(regions, detectOPF(ctx, getOPFConfig(), s)...)
814		return applyRegions(s, regions)
815	}
816	
817	// JSONLContentWithPrivacyFilter augments JSONLContent with the OpenAI
818	// Privacy Filter via batched inference. Walks the content twice: REDACTED 1
819	// collects unique prose-shaped leaves into a single RedactBatch call;
820	// REDACTED 2 applies the eight regex layers per leaf plus the cached OPF spans
821	// for that leaf. One OPF shell-out covers the whole transcript instead of
822	// one per leaf — without batching, a typical 500-leaf transcript would
823	// take many minutes per commit.
824	//
825	// Falls back to the plain JSONLContent flow when OPF is unconfigured, the
826	// breaker is tripped, no categories are enabled, or the batch call errors.
827	func JSONLContentWithPrivacyFilter(ctx context.Context, content string) (string, error) {
828		cfg := getOPFConfig()
829		if cfg == nil || !cfg.Enabled || cfg.runtime == nil || opfBreakerTripped.Load() {
830			return jsonlContentImpl(content, String, concurrencySafeRedactor)
831		}
832		cats := enabledCategories(cfg)
833		if len(cats) == 0 {
834			return jsonlContentImpl(content, String, concurrencySafeRedactor)
835		}
836	
837		// Pass 1: collect eligible (has-space, deduped) leaves. The collector
838		// closure returns identity so the JSONL walker doesn't mutate content.
839		seen := make(map[string]struct{})
840		var inputs []string
841		if _, err := jsonlContentImpl(content, func(v string) string {
842			if strings.ContainsRune(v, ' ') {
843				if _, ok := seen[v]; !ok {
844					seen[v] = struct{}{}
845					inputs = append(inputs, v)
846				}
847			}
848			return v
849		}, concurrencyUnsafeRedactor); err != nil {
850			return "", err
851		}
852	
853		// Pass 2: single batched OPF call.
854		spansByInput := make(map[string][]Span, len(inputs))
855		if len(inputs) > 0 {
856			fmt.Fprintln(opfStderr, "→ OpenAI Privacy Filter: scanning transcript…")
857			start := time.Now()
858			batched, err := cfg.runtime.RedactBatch(ctx, inputs, cats)
859			if err != nil {
860				handleOPFFailure(ctx, cfg, err)
861				return jsonlContentImpl(content, String, concurrencySafeRedactor)
862			}
863			fmt.Fprintf(opfStderr, "✓ OpenAI Privacy Filter: done (%.1fs)\n", time.Since(start).Seconds())
864			// A short return means the runtime gave us fewer span slices than
865			// inputs — the tail leaves would receive zero OPF spans and the
866			// caller would proceed as if OPF had found nothing. That silently
867			// produces under-redacted output and is indistinguishable from a
868			// "no PII present" result. Treat as a runtime contract violation:
869			// trip the breaker so the pre-push rewrite's post-loop
870			// OPFBreakerTripped() check aborts before the Entire-OPF-Applied
871			// trailer can be attached to under-redacted commits. The production
872			// shell-out always returns len(inputs), so this only fires for a
873			// misbehaving custom runtime — but the cost of leaving it dormant
874			// is too high for a privacy contract.
875			if len(batched) != len(inputs) {
876				shortErr := fmt.Errorf("opf runtime returned %d span slices for %d inputs", len(batched), len(inputs))
877				handleOPFFailure(ctx, cfg, shortErr)
878				return jsonlContentImpl(content, String, concurrencySafeRedactor)
879			}
880			for i, in := range inputs {
881				spansByInput[in] = batched[i]
882			}
883		}
884	
885		// Pass 3: per-leaf regex layers + cached OPF spans.
886		return jsonlContentImpl(content, func(v string) string {
887			regions := detectAllLayers(v)
888			regions = append(regions, opfSpanRegions(v, spansByInput[v], cfg)...)
889			return applyRegions(v, regions)
890		}, concurrencySafeRedactor)
891	}
892	
893	// applyJSONReplacements applies collected (original, redacted) string pairs
894	// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
895	// Returns s unchanged if repls is empty.
896	func applyJSONReplacements(s string, repls []jsonReplacement) (string, error) {
897		if len(repls) == 0 {
898			return s, nil
899		}
900		for _, r := range repls {
901			origJSON, err := jsonEncodeString(r.original)
902			if err != nil {
903				return "", err
904			}
905			replJSON, err := jsonEncodeString(r.redacted)
906			if err != nil {
907				return "", err
908			}
909			if r.key == "" {
910				s = strings.ReplaceAll(s, origJSON, replJSON)
911				continue
912			}
913			keyJSON, err := jsonEncodeString(r.key)
914			if err != nil {
915				return "", err
916			}
917			s = replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON)
918		}
919		return s, nil
920	}
921	
922	// replaceKeyedJSONValue replaces every occurrence of origJSON that follows
923	// keyJSON + optional whitespace + ':' + optional whitespace. Restricts
924	// substitution to value positions so a key's own redacted text is not
925	// rewritten when it collides with another field's value.
926	func replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON string) string {
927		if !strings.Contains(s, keyJSON) {
928			return s
929		}
930		var b strings.Builder
931		b.Grow(len(s))
932		i := 0
933		for i < len(s) {
934			j := strings.Index(s[i:], keyJSON)
935			if j < 0 {
936				b.WriteString(s[i:])
937				break
938			}
939			keyEnd := i + j + len(keyJSON)
940			b.WriteString(s[i : i+j])
941			b.WriteString(keyJSON)
942			p := keyEnd
943			for p < len(s) && isJSONWhitespace(s[p]) {
944				p++
945			}
946			if p >= len(s) || s[p] != ':' {
947				i = keyEnd
948				continue
949			}
950			p++
951			for p < len(s) && isJSONWhitespace(s[p]) {
952				p++
953			}
954			if p+len(origJSON) <= len(s) && s[p:p+len(origJSON)] == origJSON {
955				b.WriteString(s[keyEnd:p])
956				b.WriteString(replJSON)
957				i = p + len(origJSON)
958				continue
959			}
960			i = keyEnd
961		}
962		return b.String()
963	}
964	
965	func isJSONWhitespace(c byte) bool {
966		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
967	}
968	
969	// isSingleJSONValue returns true if the decoder has reached EOF (no more
970	// top-level values). This distinguishes a single JSON value (e.g., pretty-printed
971	// object) from JSONL (multiple concatenated values). We attempt a second Decode
972	// and require io.EOF rather than relying on dec.More(), which is documented for
973	// use inside arrays/objects and not for top-level value boundaries.
974	func isSingleJSONValue(dec *json.Decoder) bool {
975		var discard json.RawMessage
976		return dec.Decode(&discard) == io.EOF
977	}
978	
979	// collectJSONLReplacements walks a parsed JSON value and collects unique
980	// string replacements via the supplied per-leaf redactor. JSONLContent
981	// REDACTEDes String; the OPF-enabled flow REDACTEDes a closure that combines the
982	// regex layers with cached batched OPF spans.
983	func collectJSONLReplacements(v any, redactor func(string) string) []jsonReplacement {
984		seen := make(map[string]bool)
985		var repls []jsonReplacement
986		var walk func(key string, credentialContext bool, v any)
987		walk = func(key string, credentialContext bool, v any) {
988			switch val := v.(type) {
989			case map[string]any:
990				if shouldSkipJSONLObject(val) {
991					return
992				}
993				childCredentialContext := credentialContext || isCredentialJSONObject(val)
994				for k, child := range val {
995					if shouldSkipJSONLField(k) {
996						continue
997					}
998					walk(k, childCredentialContext, child)
999				}
1000			case []any:
1001				for _, child := range val {
1002					walk("", credentialContext, child)
1003				}
1004			case string:
1005				redacted := redactor(val)
1006				if redacted == val && isCredentialJSONSecretKey(key, credentialContext) && hasNonPlaceholderPasswordValue(val) {
1007					redacted = RedactedPlaceholder
1008				}
1009				if redacted != val {
1010					seenKey := key + "\x00" + val
1011					if !seen[seenKey] {
1012						seen[seenKey] = true
1013						repls = append(repls, jsonReplacement{key: key, original: val, redacted: redacted})
1014					}
1015				}
1016			}
1017		}
1018		walk("", false, v)
1019		return repls
1020	}
1021	
1022	// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
1023	// Skips signature fields (any key ending in "signature"), ID fields (ending in "id"/"ids"),
1024	// and common path/directory fields.
1025	func shouldSkipJSONLField(key string) bool {
1026		lower := strings.ToLower(key)
1027	
1028		// Skip signature fields: cryptographic attestations, not secrets. Covers
1029		// "signature" (Claude Code) and provider variants like "thinkingSignature"
1030		// (Oh My Pi). Their values are high-entropy base64, so the entropy scanner
1031		// would otherwise redact them — corrupting extended-thinking signatures and
1032		// breaking transcript replay ("Invalid `signature` in `thinking` block").
1033		if strings.HasSuffix(lower, "signature") {
1034			return true
1035		}
1036	
1037		// Skip ID fields
1038		if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
1039			return true
1040		}
1041	
1042		// Skip common path and directory fields from agent transcripts.
1043		// These appear frequently in tool calls and are structural, not secrets.
1044		switch lower {
1045		case "filepath", "file_path", "cwd", "root", "directory", "dir", "path":
1046			return true
1047		}
1048	
1049		return false
1050	}
1051	
1052	// shouldSkipJSONLObject returns true if the object has "type":"image" or "type":"image_url".
1053	func shouldSkipJSONLObject(obj map[string]any) bool {
1054		t, ok := obj["type"].(string)
1055		return ok && (strings.HasPrefix(t, "image") || t == "base64")
1056	}
1057	
1058	func shannonEntropy(s string) float64 {
1059		if len(s) == 0 {
1060			return 0
1061		}
1062		freq := make(map[byte]int)
1063		for i := range len(s) {
1064			freq[s[i]]++
1065		}
1066		length := float64(len(s))
1067		var entropy float64
1068		for _, count := range freq {
1069			p := float64(count) / length
1070			entropy -= p * math.Log2(p)
1071		}
1072		return entropy
1073	}
1074	
1075	// jsonEncodeString returns the JSON encoding of s without HTML escaping.
1076	func jsonEncodeString(s string) (string, error) {
1077		var buf bytes.Buffer
1078		enc := json.NewEncoder(&buf)
1079		enc.SetEscapeHTML(false)
1080		if err := enc.Encode(s); err != nil {
1081			return "", fmt.Errorf("json encode string: %w", err)
1082		}
1083		return strings.TrimSuffix(buf.String(), "\n"), nil
1084	}
1085

