package redact

import (
	"encoding/json"
	"strings"
	"testing"
)

// gitHubPATFixture is a syntactically valid but fake GitHub personal access
// token. Every layer flags it, so it isolates the JSONL replacement machinery
// from detection coverage.
const gitHubPATFixture = "ghp_A1b2C3d4E5f6G7h8I9j0K1l2M3n4O5p6Q7r8" //nolint:gosec // fake credential fixture

// TestJSONLRedactionSurvivesNonCanonicalEncoding pins the fail-closed contract
// for leaves whose raw byte encoding differs from Go's canonical encoder
// output.
