// applyJSONReplacementsFailClosed applies repls to the raw JSON text raw and
// guarantees that every one of them lands.
//
// The fast path patches raw bytes, so a line with nothing to redact — and the
// untouched remainder of a line that does — comes back byte for byte. That is
// load-bearing: the incremental redaction cache in
// cmd/entire/cli/checkpoint/redact_cache.go reuses the previous checkpoint's
// redacted prefix, and CheckpointTranscriptSize compares blob sizes.
//
// The fast path can only patch bytes it can find, and it looks for Go's
// encoding of each leaf. Producers do not all encode the way Go does: Node's
// JSON.stringify emits U+2028/U+2029 raw where Go escapes them (Claude Code,
// Gemini CLI, opencode and Copilot CLI are all Node-based), PHP's json_encode
// emits \/ by default, and a lone surrogate — from a streaming chunk boundary
// that split a pair — decodes to U+FFFD and never re-encodes to itself. When
// the search misses, this used to return the line unchanged with the secret
// intact and no error. Now the miss is detected and the line is redacted by
// re-encoding it canonically instead, where the leaves are by construction
// findable. Formatting of that one line is lost; the secret is not.
func applyJSONReplacementsFailClosed(raw string, repls []jsonReplacement) (string, error) {
	result, unapplied, err := applyJSONReplacements(raw, repls)
	if err != nil {
		return "", err
	}
	if unapplied == 0 {
		return result, nil
	}
	lead, mid, trail := splitSurroundingSpace(raw)
	rewritten, err := redactViaCanonicalJSON(mid, repls)
	if err != nil {
		return "", err
	}
	return lead + rewritten + trail, nil
}

// applyJSONReplacements applies collected (original, redacted) string pairs
// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
// Returns s unchanged if repls is empty.
//
// The returned count is the number of replacements that found no target and
// were therefore NOT applied. A non-zero count means s encodes at least one
// leaf differently from Go's encoder, and s must not be shipped as redacted;
// applyJSONReplacementsFailClosed is the caller that acts on it.
//
// Keyed replacements run before keyless ones so that count is trustworthy: a
// keyless ReplaceAll rewrites every occurrence of a value, including one
// sitting in a keyed position, which would leave the keyed replacement with
// nothing to find and look like an encoding mismatch. The reverse cannot
// happen — a keyed replacement only rewrites text immediately following
// `"key":`, and a keyless target (an array element or the root value) never
// occupies that position.
func applyJSONReplacements(s string, repls []jsonReplacement) (string, int, error) {
	if len(repls) == 0 {
		return s, 0, nil
	}
	unapplied := 0
	for _, keyedPass := range []bool{true, false} {
		for _, r := range repls {
			if (r.key != "") != keyedPass {
				continue
			}
			origJSON, err := jsonEncodeString(r.original)
			if err != nil {
				return "", 0, err
			}
			replJSON, err := jsonEncodeString(r.redacted)
			if err != nil {
				return "", 0, err
			}
			var applied int
			if keyedPass {
				keyJSON, err := jsonEncodeString(r.key)
				if err != nil {
					return "", 0, err
				}
				s, applied = replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON)
			} else {
				applied = strings.Count(s, origJSON)
				if applied > 0 {
					s = strings.Replace(s, origJSON, replJSON, applied)
				}
			}
			if applied == 0 {
				unapplied++
			}
		}
	}
	return s, unapplied, nil
}

// redactViaCanonicalJSON re-encodes one JSON document into Go's canonical form
// and applies repls to that, so every leaf is spelled the way
// jsonEncodeString spells it and every replacement is findable.
//
// Only reached when the byte-preserving fast path could not find a leaf, so
// the cost of the extra parse and encode is paid on pathological input only.
// Object key order and any original whitespace inside the document are lost;
// numbers are decoded as json.Number so a 19-digit id does not come back as
// 1.2345678901234568e+18. A replacement that still fails to land here is not
// reachable by construction, so it is reported as an error rather than
// shipped: no caller may emit content this function could not redact.
func redactViaCanonicalJSON(raw string, repls []jsonReplacement) (string, error) {
	dec := json.NewDecoder(strings.NewReader(raw))
	dec.UseNumber()
	var parsed any
	if err := dec.Decode(&parsed); err != nil {
		return "", fmt.Errorf("re-encoding JSON for redaction: %w", err)
	}
	canonical, err := jsonEncodeValue(parsed)
	if err != nil {
		return "", err
	}
	out, unapplied, err := applyJSONReplacements(canonical, repls)
	if err != nil {
		return "", err
	}
	if unapplied > 0 {
		return "", fmt.Errorf("redaction did not apply to %d of %d detected value(s)", unapplied, len(repls))
	}
	return out, nil
}

// splitSurroundingSpace splits s into its leading whitespace, its
// whitespace-trimmed middle, and its trailing whitespace, using the same
// notion of whitespace as strings.TrimSpace. Lets the canonical rewrite
// replace a line's JSON without swallowing the indentation or the "\r" of a
// CRLF transcript around it.
func splitSurroundingSpace(s string) (lead, mid, trail string) {
	left := strings.TrimLeftFunc(s, unicode.IsSpace)
	lead = s[:len(s)-len(left)]
	mid = strings.TrimRightFunc(left, unicode.IsSpace)
	trail = left[len(mid):]
	return lead, mid, trail
}

