// jsonEncodeString returns the JSON encoding of s without HTML escaping.
func jsonEncodeString(s string) (string, error) {
	return jsonEncodeValue(s)
}

// jsonEncodeValue returns the JSON encoding of v without HTML escaping and
// without the trailing newline Encode appends. Sharing one encoder
// configuration with jsonEncodeString is what makes redactViaCanonicalJSON
// work: every string leaf in the encoded document is spelled exactly as
// jsonEncodeString spells it.
func jsonEncodeValue(v any) (string, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(v); err != nil {
		return "", fmt.Errorf("json encode value: %w", err)
	}
	return strings.TrimSuffix(buf.String(), "\n"), nil
}

